#!/bin/bash
# Compile the guest SpiderMonkey PBL JIT object (PBLIC IC compiler, PBLBC method
# compiler). Source tools/nightly-musl/recipe/environment.sh first (the clang
# wrapper takes libc++ include paths from NIX_CXXSTDLIB_COMPILE), then set
# TMPDIR/TMP/TEMP to a disk scratch path.
# $PBL_BUILD/src holds upstream PortableBaselineInterpret.cpp with
# PortableBaselineInterpret.patch applied, plus PblIc.inc, PblIcOps.h and
# PblMethod.inc from this directory; the object goes to $PBL_BUILD/obj and
# replaces PortableBaselineInterpret.o in libjs_static.a (llvm-ar r).
set -e
/nix/store/j8mdl69qafyijllv7s703219nb5fnrdp-wasm32-unknown-linux-musl-llvm-toolchain-wrapper-22.1.8/bin/wasm32-unknown-linux-musl-clang++ -std=gnu++20 -o ${PBL_BUILD:-/mnt/p3/codex-build/opus-ffgpu/bc1}/obj/PortableBaselineInterpret.o -c  -I/mnt/p6/build/firefox-nightly-musl-jit-full-20261002/obj-nightly/dist/stl_wrappers -I/mnt/p6/build/firefox-nightly-musl-jit-full-20261002/obj-nightly/dist/system_wrappers -include /mnt/p6/build/firefox-nightly-musl-jit-full-20261002/source/firefox-159.0a1/config/gcc_hidden.h -U_FORTIFY_SOURCE -D_FORTIFY_SOURCE=2 -fstack-protector-strong -fstrict-flex-arrays=1 -DNDEBUG=1 -DTRIMMED=1 -DJS_CACHEIR_SPEW -DJS_STRUCTURED_SPEW -DJS_HAS_CTYPES -DUSE_LIBZ_RS -DEXPORT_JS_API -DMOZ_HAS_MOZGLUE -DMOZ_SUPPORT_LEAKCHECKING -I/mnt/p6/build/firefox-nightly-musl-jit-full-20261002/obj-nightly/js/src -I/mnt/p6/build/firefox-nightly-musl-jit-full-20261002/source/firefox-159.0a1/js/src -I/mnt/p6/build/firefox-nightly-musl-jit-full-20261002/obj-nightly/dist/include -I/mnt/p6/build/firefox-nightly-musl-jit-full-20261002/obj-nightly/dist/include/nspr -I/mnt/p6/build/firefox-nightly-musl-jit-full-20261002/obj-nightly/dist/include/nss -DMOZILLA_CLIENT -include /mnt/p6/build/firefox-nightly-musl-jit-full-20261002/obj-nightly/mozilla-config.h -fno-rtti -pthread -fno-sized-deallocation -fno-aligned-new -fno-math-errno -fno-exceptions -fdiagnostics-absolute-paths -fPIC -Wno-error=implicit-int-conversion -Xclang -fc++-abi=webassembly -O3 -fno-omit-frame-pointer -funwind-tables -Wall -Wbitfield-enum-conversion -Wempty-body -Wformat-type-confusion -Wignored-qualifiers -Wimplicit-int-enum-cast -Woctal-prefix-extension -Wpointer-arith -Wshift-bool -Wshadow-field-in-constructor-modified -Wsign-compare -Wtautological-constant-in-range-compare -Wtype-limits -Wno-error=tautological-type-limit-compare -Wunreachable-code -Wunreachable-code-return -Wunused-but-set-parameter -Wvector-conversion -Wno-invalid-offsetof -Wclass-varargs -Wempty-init-stmt -Wfloat-overflow-conversion -Wfloat-zero-conversion -Wloop-analysis -Wno-range-loop-analysis -Wno-deprecated-anon-enum-enum-conversion -Wno-deprecated-enum-enum-conversion -Wdeprecated-literal-operator -Winvalid-utf8 -Wcomma -Wimplicit-fallthrough -Wstring-conversion -Wno-inline-new-delete -Wno-error=deprecated-declarations -Wno-error=array-bounds -Wno-error=free-nonheap-object -Wno-error=atomic-alignment -Wno-error=deprecated-builtins -Wformat -Wformat-security -Wno-psabi -Wthread-safety -Wno-error=builtin-macro-redefined -Wno-vla-cxx-extension -Wno-unknown-warning-option -Wno-character-conversion -Werror=format -Wdeprecated-this-capture -Wdeprecated-anon-enum-enum-conversion -Wdeprecated-enum-enum-conversion -fno-strict-aliasing -ffp-contract=off    ${PBL_BUILD:-/mnt/p3/codex-build/opus-ffgpu/bc1}/src/PortableBaselineInterpret.cpp
